alter table public.curriculum add column if not exists ipas text not null default '', add column if not exists pancasila text not null default '', add column if not exists seni text not null default '';
update public.curriculum set
 ipas=case when level<=4 then 'Mengamati makhluk hidup, benda, cuaca, dan lingkungan sekitar melalui kegiatan langsung.' when level<=8 then 'Mengelompokkan makhluk hidup dan benda serta menjelaskan perubahan sederhana di lingkungan.' when level<=12 then 'Menjelaskan energi, materi, tubuh, lingkungan, dan hubungan manusia dengan alam berdasarkan pengamatan.' else 'Menganalisis ekosistem, energi, perubahan bumi, dan data pengamatan untuk memecahkan masalah sederhana.' end,
 pancasila=case when level<=4 then 'Mengenal aturan, simbol, identitas diri, dan kebiasaan hidup bersama.' when level<=8 then 'Menjelaskan hak, kewajiban, keberagaman, dan aturan bersama dalam kehidupan sehari-hari.' when level<=12 then 'Menerapkan nilai Pancasila dalam keputusan, kerja sama, dan tanggung jawab di lingkungan.' else 'Menganalisis persoalan kewargaan, musyawarah, keadilan, dan tanggung jawab sebagai warga.' end,
 seni=case when level<=4 then 'Mengeksplorasi garis, warna, bunyi, gerak, dan karya sederhana.' when level<=8 then 'Membuat karya seni visual, musik, atau gerak dengan pola dan tujuan sederhana.' when level<=12 then 'Merancang karya dengan teknik, unsur, dan apresiasi terhadap karya orang lain.' else 'Mengembangkan karya lintas media, menjelaskan pilihan artistik, dan memberi apresiasi berbasis alasan.' end;
